       , TASK_STATUS = #{taskStatus} 
       , IS_TEST     = #{isTest}     
       , TASK_DEPTH  = #{taskDepth}  
       , STG_ID      = #{stgId}      
       , PT_TASK_ID  = #{ptTaskId}  
       , TASK_SEQ    = #{taskSeq}    
       , TASK_ST     = #{taskSt}     
