SELECT /* QueryID : com.demo.proworks.task.design.selectListDesign */ taskId, taskName, taskDes, taskStatus, isTest, taskDepth, stgId, ptTaskId, taskSeq, taskSt, taskEt, taskRst, taskRet, taskAsi, taskRate, pjtId, ptTaskName, stgName FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT t.TASK_ID as taskId, t.TASK_NAME as taskName, t.TASK_DES as taskDes, t.TASK_STATUS as taskStatus, t.IS_TEST as isTest, t.TASK_DEPTH as taskDepth, t.STG_ID as stgId, t.PT_TASK_ID as ptTaskId, t.TASK_SEQ as taskSeq, t.TASK_ST as taskSt, t.TASK_ET as taskEt, t.TASK_RST as taskRst, t.TASK_RET as taskRet, t.TASK_ASI as taskAsi, t.TASK_RATE as taskRate, t.PJT_ID as pjtId, pt.TASK_NAME as ptTaskName, s.STG_NAME as stgName FROM TASK t LEFT JOIN TASK pt ON t.PT_TASK_ID = pt.TASK_ID LEFT JOIN STG s ON t.STG_ID = s.STG_ID WHERE 1=1
AND t.TASK_NAME like '%${scTaskName}%'
AND t.TASK_STATUS like '%${scTaskStatus}%'
AND t.IS_TEST like '%${scIsTest}%'
AND t.STG_ID like '%${scStgId}%'
) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}

WITH RECURSIVE task_tree AS ( -- 1단계: 최상위 업무들 SELECT task_id, task_name, pt_task_id, task_depth, task_seq, stg_id, pjt_id, CAST(LPAD(task_seq, 3, '0') AS VARCHAR(100)) as sort_path FROM task t WHERE pt_task_id = 0 and pjt_id = #{pjtId}
UNION ALL
-- 2-3단계: 하위 업무들 재귀 조회 SELECT t.task_id, t.task_name, t.pt_task_id, t.task_depth, t.task_seq, t.stg_id, t.pjt_id, CAST(CONCAT(tt.sort_path, '-', LPAD(t.task_seq, 3, '0')) AS VARCHAR(100)) as sort_path FROM task t INNER JOIN task_tree tt ON t.pt_task_id = tt.task_id WHERE t.task_depth <= 3 ) SELECT task_id as taskId, task_name as taskName, pt_task_id as ptTaskId, task_depth as taskDepth, task_seq as taskSeq, stg_id as stgId, pjt_id as pjtId FROM task_tree WHERE pjt_id = #{pjtId} ORDER BY stg_id, sort_path
